      ) : null}

      {confirmDelete ? (
        <ConfirmDialog
          title="删除执行记录"
          busy={deleting}
          message={<>确定删除执行记录「{confirmDelete.name}」吗？记录与截图会被一并删除，不可撤销。</>}
          onCancel={() => setConfirmDelete(null)}
          onConfirm={() => void doDelete()}
        />
      ) : null}
    </section>
  )
}
