              ），或开发模式下用 <code>npm run dev</code>。
            </Notice>
          ) : null}

          {view !== 'run' ? (
            <nav className="tabs">
              <button
                type="button"
                className={`tab${view === 'cases' && !editorOpen ? ' tab--active' : ''}`}
