{"content": "// 诊断：验证沙箱下 esbuild 二进制能否以「管道 stdio」启动（Vite 配置加载需要它）。
const { spawn } = require('child_process')
const path = require('path')
const fs = require('fs')

const bin = path.join(__dirname, 'node_modules', '@esbuild', 'win32-x64', 'esbuild.exe')
const log = []
log.push(`bin exists: ${fs.existsSync(bin)} -> ${bin}`)

function run(label, stdio) {
  return new Promise((resolve) => {
    let child
    try {
      child = spawn(bin, ['--version'], { windowsHide: true, stdio })
    } catch (error) {
      log.push(`${label}: spawn throw ${error.message}`)
      return resolve()
    }
    let out = ''
    if (child.stdout) child.stdout.on('data', (chunk) => (out += chunk.toString()))
    child.on('error', (error) => {
      log.push(`${label}: error ${error.code ?? ''} ${error.message}`)
      resolve()
    })
    child.on('close', (code) => {
      log.push(`${label}: close code=${code} stdout=${JSON.stringify(out.trim())}`)
      resolve()
    })
  })
}

;(async () => {
  await run('pipe-stdio', ['pipe', 'pipe', 'inherit'])
  await run('inherit-stdio', ['inherit', 'inherit', 'inherit'])
  fs.writeFileSync(path.join(__dirname, 'web', '.esbuild-probe.log'), log.join('\n'), 'utf8')
  console.log('probe done')
})()
