import { createRequire } from 'node:module'
import { writeFileSync } from 'node:fs'
import { join } from 'node:path'

const require = createRequire(import.meta.url)
const resultFile = join(process.cwd(), 'web', '.patch-probe.log')
const lines = []

const cp = require('node:child_process')
lines.push(`child_process.exec 类型：${typeof cp.exec}`)

let patched = false
try {
  const originalExec = cp.exec
  cp.exec = function patchedExec(command, options, callback) {
    if (typeof options === 'function') {
      callback = options
      options = undefined
    }
    if (String(command).trim() === 'net use') {
      lines.push('已拦截 net use，不再真正执行')
      if (typeof callback === 'function') setTimeout(() => callback(null, '', ''), 0)
      return { on() {}, kill() {}, stdin: null, stdout: null, stderr: null }
    }
    return originalExec.call(this, command, options, callback)
  }
  patched = true
} catch (error) {
  lines.push(`改写失败：${error.message}`)
}
