{"content": "/**
 * 沙箱内可用的构建入口（等价于 vite.config.ts 的配置）。
 *
 * 背景：本机沙箱禁止 Node 以「管道 stdio」spawn 子进程（spawn EPERM）。而
 *   1) Vite 加载 vite.config.ts 需要 esbuild 服务进程；
 *   2) Vite 转换 .tsx 需要 esbuild 服务进程；
 *   3) Vite 的 windowsSafeRealPathSync 会 exec("net use")。
 * 三者都会踩到这个限制，所以这里：
 *   - 把 esbuild 的异步 API（build/transform/formatMessages/analyzeMetafile）重定向到同名 Sync 版本
 *     （Sync 版本是直接 spawn + inherit stdio，沙箱下可用，无需长连接服务进程）；
 *   - 拦掉 `net use` 探测；
 *   - 直接用 Vite 的 Node API 传入与 vite.config.ts 等价的内联配置，跳过配置文件打包。
 *
 * 正常环境（无沙箱限制）依然可以直接执行：
 *   node node_modules/vite/bin/vite.js build
 */
import { createRequire } from 'node:module'
import { readdirSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const require = createRequire(import.meta.url)
const resultFile = join(process.cwd(), 'web', '.build-result.log')
const writeResult = (text) => {
  try {
    writeFileSync(resultFile, `${text}\n`, 'utf8')
  } catch {
    /* ignore */
  }
}

writeResult(`开始构建 ${new Date().toLocaleString('zh-CN')}`)

// ---------------------------------------------------------------- 沙箱补丁 1：esbuild 异步 API -> Sync
const esbuild = require('esbuild')
const pairs = [
  ['build', 'buildSync'],
  ['transform', 'transformSync'],
  ['formatMessages', 'formatMessagesSync'],
  ['analyzeMetafile', 'analyzeMetafileSync'],
]
const patched = []
for (const [asyncName, syncName] of pairs) {
  const syncFn = esbuild[syncName]
  if (typeof syncFn === 'function' && typeof esbuild[asyncName] === 'function') {
    esbuild[asyncName] = (...args) => syncFn(...args)
    patched.push(asyncName)
  }
}

// ---------------------------------------------------------------- 沙箱补丁 2：拦掉 net use
const childProcess = require('node:child_process')
const originalExec = childProcess.exec
childProcess.exec = function sandboxExec(command, options, callback) {
  if (String(command).trim() === 'net use') {
    if (typeof callback === 'function') setTimeout(() => callback(null, '', ''), 0)
    return { on() {}, kill() {}, stdin: null, stdout: null, stderr: null }
  }
  return originalExec.call(this, command, options, callback)
}

try {
  const { build } = await import('vite')
  const react = (await import('@vitejs/plugin-react')).default

  await build({
    root: 'web',
    base: '/',
    plugins: [react()],
    logLevel: 'info',
    build: {
      outDir: 'dist',
      emptyOutDir: true,
      sourcemap: false,
    },
  })

  const dist = join(process.cwd(), 'web', 'dist')
  const assets = join(dist, 'assets')
  const lines = [
    'vite build 完成 ✅',
    `已重定向为 Sync 的 esbuild API：${patched.join(', ') || '（无）'}`,
    `index.html: ${statSync(join(dist, 'index.html')).size} 字节`,
    ...readdirSync(assets).map((name) => `assets/${name}: ${statSync(join(assets, name)).size} 字节`),
  ]
  writeFileSync(join(dist, 'build-summary.txt'), `${lines.join('\n')}\n`, 'utf8')
  writeResult(lines.join('\n'))
  console.log(lines.join('\n'))
} catch (error) {
  writeResult(`构建失败 ❌\n${error?.stack ?? error}`)
  process.exitCode = 1
}
