import { createRequire } from 'node:module'
import { writeFileSync } from 'node:fs'
import { join } from 'node:path'

const require = createRequire(import.meta.url)
const lines = []
const esbuild = require('esbuild')

lines.push('--- require("esbuild") 自身属性描述符 ---')
for (const key of ['build', 'transform']) {
  const d = Object.getOwnPropertyDescriptor(esbuild, key)
  lines.push(`${key}: ${JSON.stringify({ get: typeof d?.get, value: typeof d?.value, writable: d?.writable, configurable: d?.configurable, enumerable: d?.enumerable })}`)
}

let defineOnCjs = 'not tried'
try {
  const syncFn = esbuild.transformSync
  Object.defineProperty(esbuild, 'transform', { value: (...args) => syncFn(...args), configurable: true })
  defineOnCjs = `ok -> ${typeof esbuild.transform}`
} catch (error) {
  defineOnCjs = `失败：${error.message}`
}
lines.push(`defineProperty(cjs.transform): ${defineOnCjs}`)

const ns = await import('esbuild')
lines.push('--- import("esbuild") 命名空间属性描述符 ---')
for (const key of ['build', 'transform']) {
  const d = Object.getOwnPropertyDescriptor(ns, key)
  lines.push(`${key}: ${JSON.stringify({ get: typeof d?.get, value: typeof d?.value, writable: d?.writable, configurable: d?.configurable, enumerable: d?.enumerable })}`)
}

let defineOnNs = 'not tried'
try {
  const syncFn = ns.transformSync
  Object.defineProperty(ns, 'transform', { value: (...args) => syncFn(...args), configurable: true })
  defineOnNs = `ok -> ${typeof ns.transform}`
} catch (error) {
  defineOnNs = `失败：${error.message}`
}
lines.push(`defineProperty(ns.transform): ${defineOnNs}`)

writeFileSync(join(process.cwd(), 'web', '.esbuild-ns.log'), `${lines.join('\n')}\n`, 'utf8')
