 *
 * 背景：本机沙箱禁止 Node 以「管道 stdio」spawn 子进程（spawn EPERM）。esbuild 的
 * 异步 API 需要长连接服务进程（管道通信），因此 Vite 加载配置/转换 TSX 时都会崩。
 *
 * 做法：
 *   1. 用 Node 的 module.registerHooks 把 Vite 看到的 `esbuild` 模块换成同名 Sync API 版本
 *      （buildSync/transformSync 直接 spawn + inherit stdio，沙箱下可用）；
 *   2. 用 VITE_CONFIG_LOADER=runner 让 Vite 用 Node 原生能力加载 vite.config.ts，
 *      跳过 esbuild 打包配置这一步；
 *   3. 用 Vite 的 Node API 传入与 vite.config.ts 等价的内联配置。
 *
 * 正常环境（无沙箱限制）依然可以直接执行：
 *   node node_modules/vite/bin/vite.js build
 */
import { registerHooks, createRequire } from 'node:module'
import { readdirSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const require = createRequire(import.meta.url)
const esbuildPath = require.resolve('esbuild').replace(/\\/g, '/')

const SANDBOX_ESBUILD_SOURCE = `
import * as real from '${esbuildPath}'
const api = { ...real }
if (typeof real.transformSync === 'function') api.transform = (...args) => real.transformSync(...args)
if (typeof real.buildSync === 'function') api.build = (...args) => real.buildSync(...args)
if (typeof real.formatMessagesSync === 'function') api.formatMessages = (...args) => real.formatMessagesSync(...args)
if (typeof real.analyzeMetafileSync === 'function') api.analyzeMetafile = (...args) => real.analyzeMetafileSync(...args)
api.context = () => {
  throw new Error('沙箱内不支持 esbuild 监听模式（context）')
}
export const { formatMessages, analyzeMetafile, build, transform, initialize, version, stop, context } = api
export default api
`

registerHooks({
  resolve(specifier, context, nextResolve) {
    if (specifier === 'esbuild') {
      return { url: 'sandbox:esbuild', format: 'module', shortCircuit: true }
    }
    return nextResolve(specifier, context)
  },
  load(url, context, nextLoad) {
    if (url === 'sandbox:esbuild') {
      return { format: 'module', source: SANDBOX_ESBUILD_SOURCE, shortCircuit: true }
    }
    return nextLoad(url, context)
  },
})

// 让 Vite 用 Node 原生加载 vite.config.ts（runner = native 类型剥离），避免 esbuild 打包配置
process.env.VITE_CONFIG_LOADER ??= 'runner'

// 拦掉 Vite 的 net use 探测（同样会以管道 stdio spawn，沙箱下抛 EPERM）
const childProcess = require('node:child_process')
const originalExec = childProcess.exec
childProcess.exec = function sandboxExec(command, options, callback) {
  if (String(command).trim() === 'net use') {
    if (typeof callback === 'function') setTimeout(() => callback(null, '', ''), 0)
    return { on() {}, kill() {}, stdin: null, stdout: null, stderr: null }
  }
  return originalExec.call(this, command, options, callback)
}

const resultFile = join(process.cwd(), 'web', '.build-result.log')
const writeResult = (text) => {
  try {
    writeFileSync(resultFile, `${text}\n`, 'utf8')
  } catch {
    /* ignore */
  }
}

writeResult(`开始构建 ${new Date().toLocaleString('zh-CN')}`)

try {
  const { build } = await import('vite')
  const react = (await import('@vitejs/plugin-react')).default

  await build({
    root: 'web',
    base: '/',
    plugins: [react()],
    logLevel: 'info',
    build: {
      outDir: 'dist',
      emptyOutDir: true,
      sourcemap: false,
    },
  })

  const dist = join(process.cwd(), 'web', 'dist')
  const assets = join(dist, 'assets')
  const lines = [
    'vite build 完成 ✅',
    `index.html: ${statSync(join(dist, 'index.html')).size} 字节`,
    ...readdirSync(assets).map((name) => `assets/${name}: ${statSync(join(assets, name)).size} 字节`),
  ]
  writeFileSync(join(dist, 'build-summary.txt'), `${lines.join('\n')}\n`, 'utf8')
  writeResult(lines.join('\n'))
  console.log(lines.join('\n'))
} catch (error) {
  writeResult(`构建失败 ❌\n${error?.stack ?? error}`)
  process.exitCode = 1
}
