{"content": "// 静态审计：核对相对导入路径是否存在、命名导入是否都被目标文件导出、
// Vite 能否解析裸模块依赖（react / react-dom），以及 main.tsx 引用的样式表是否存在。
const fs = require('node:fs')
const path = require('node:path')

const root = path.resolve(__dirname, '..')
const SRC = path.join(root, 'web', 'src')
const ALLOWED_BARE = new Set(['react', 'react-dom', 'react/jsx-runtime', 'react-dom/client'])

const files = []
const walk = (dir) => {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) walk(full)
    else if (/\.(tsx?|css)$/.test(entry.name)) files.push(full)
  }
}
walk(SRC)

const problems = []
const checkedImports = []

for (const file of files) {
  if (!/\.tsx?$/.test(file)) continue
  const text = fs.readFileSync(file, 'utf8')
  const re = /import\s+(?:([\w*\s{},$]+?)\s+from\s+)?['"]([^'"]+)['"]/g
  let m
  while ((m = re.exec(text)) !== null) {
    const clause = (m[1] ?? '').trim()
    const spec = m[2]
    const rel = path.relative(root, file).replace(/\\/g, '/')

    if (!spec.startsWith('.')) {
      if (!ALLOWED_BARE.has(spec)) problems.push(`${rel}: 引用了未允许的裸依赖 "${spec}"`)
      else checkedImports.push(`${rel} -> ${spec} (裸依赖，已在依赖清单内)`)
      continue
    }

    const base = path.resolve(path.dirname(file), spec)
    const candidates = [base, `${base}.ts`, `${base}.tsx`, `${base}.css`, path.join(base, 'index.ts'), path.join(base, 'index.tsx')]
    const target = candidates.find((p) => fs.existsSync(p) && fs.statSync(p).isFile())
    if (!target) {
      problems.push(`${rel}: 导入路径不存在 "${spec}"`)
      continue
    }
    checkedImports.push(`${rel} -> ${spec}`)

    // 命名导入核对（只看相对 .ts/.tsx，且不是 import * as / 默认导入）
    if (!/\.tsx?$/.test(target)) continue
    const names = []
    const namedMatch = clause.match(/\{([^}]*)\}/)
    if (namedMatch) {
      for (const raw of namedMatch[1].split(',')) {
        const name = raw.trim().split(/\s+as\s+/)[0].trim()
        if (name) names.push(name)
      }
    }
    if (!names.length) continue
    const targetText = fs.readFileSync(target, 'utf8')
    const targetRel = path.relative(root, target).replace(/\\/g, '/')
    for (const name of names) {
      const patterns = [
        new RegExp(`export\\s+(?:const|function|async function|class|type|interface|enum)\\s+${name}\\b`),
        new RegExp(`export\\s*\\{[^}]*\\b${name}\\b`),
        new RegExp(`export\\s+default\\s+${name}\\b`),
      ]
      if (!patterns.some((p) => p.test(targetText))) {
        problems.push(`${rel}: 命名导入 "${name}" 在 ${targetRel} 中找不到对应导出`)
      }
    }
  }
}

// 默认导入核对：`import X from './y'` 需要目标有 default 导出
for (const file of files) {
  if (!/\.tsx?$/.test(file)) continue
  const text = fs.readFileSync(file, 'utf8')
  const re = /import\s+([A-Za-z_$][\w$]*)\s+from\s+['"](\.[^'"]+)['"]/g
  let m
  while ((m = re.exec(text)) !== null) {
    const name = m[1]
    const base = path.resolve(path.dirname(file), m[2])
    const target = [base, `${base}.ts`, `${base}.tsx`].find((p) => fs.existsSync(p) && fs.statSync(p).isFile())
    if (!target) continue
    const targetText = fs.readFileSync(target, 'utf8')
    const rel = path.relative(root, file).replace(/\\/g, '/')
    const targetRel = path.relative(root, target).replace(/\\/g, '/')
    const ok =
      new RegExp(`export\\s+default\\b`).test(targetText) ||
      new RegExp(`export\\s+default\\s+(?:function|class)\\s+${name}\\b`).test(targetText)
    if (!ok) problems.push(`${rel}: 默认导入 "${name}"，但 ${targetRel} 没有 default 导出`)
  }
}

// 入口与样式表
const main = path.join(SRC, 'main.tsx')
if (!fs.existsSync(main)) problems.push('缺少 web/src/main.tsx')
if (!fs.existsSync(path.join(SRC, 'styles.css'))) problems.push('缺少 web/src/styles.css')
const html = path.join(root, 'web', 'index.html')
if (fs.existsSync(html) && !/src="\/src\/main\.tsx"/.test(fs.readFileSync(html, 'utf8'))) {
  problems.push('web/index.html 未引用 /src/main.tsx')
}

const report = [
  `扫描文件：${files.length} 个`,
  `导入检查：${checkedImports.length} 条`,
  problems.length ? `发现问题（${problems.length}）：\n- ${problems.join('\n- ')}` : '导入/导出核对：全部一致 ✅',
  '',
  '导入明细：',
  ...checkedImports.map((line) => `  ${line}`),
].join('\n')

fs.writeFileSync(path.join(root, 'web', '.import-audit.log'), `${report}\n`, 'utf8')
console.log(problems.length ? `问题 ${problems.length} 个` : '导入/导出核对通过')
", "file_path": "E:\testPlatform\code\web\.import-audit.cjs"}

