{"content": "// 一次性类型检查脚本（不落盘到仓库：用完即删）。
// 用法：node web/.typecheck.cjs  → 结果写入 web/.typecheck.log
const ts = require('typescript')
const fs = require('fs')
const path = require('path')

const projectDir = path.resolve(__dirname, '..')
const configPath = path.join(projectDir, 'tsconfig.json')
const configFile = ts.readConfigFile(configPath, ts.sys.readFile)
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, projectDir)
const program = ts.createProgram(parsed.fileNames, {
  ...parsed.options,
  noUnusedLocals: true,
  noFallthroughCasesInSwitch: true,
})
const diagnostics = ts.getPreEmitDiagnostics(program)

const lines = diagnostics.map((d) => {
  const msg = ts.flattenDiagnosticMessageText(d.messageText, ' ')
  if (d.file && d.start !== undefined) {
    const { line, character } = d.file.getLineAndCharacterOfPosition(d.start)
    return `${path.relative(projectDir, d.file.fileName)}:${line + 1}:${character + 1} - ${msg}`
  }
  return `(global) - ${msg}`
})

fs.writeFileSync(
  path.join(__dirname, '.typecheck.log'),
  lines.length ? lines.join('\n') : 'TYPE CHECK OK（无诊断）',
  'utf8',
)
console.log(`诊断数量：${diagnostics.length}`)
", "file_path": "E:\testPlatform\code\web\.typecheck.cjs"}

